const attempt = $runIndex + 1;
const item = $input.first()?.json ?? {};

function fail(reason) {
  return [{ json: { valid: false, attempt, reason } }];
}

const error = item.error;
if (error) {
  const reason = typeof error === 'string'
    ? error
    : error.message || error.description || JSON.stringify(error);

  return fail(reason);
}

const raw = item.output;
const output = typeof raw === 'string'
  ? raw.trim().replace(/\r\n?/g, '\n')
  : '';

if (!output) return fail('The model returned no brief.');

// Read the original RSS records, not URLs supplied by the model.
const articles = $('Aggregate').first(0, 0).json.articles;
const allowed = new Map();
for (const article of articles) {
  const url = (article.link || '').trim();
  /*if (/^https?:\/\/\S+$/i.test(url)) allowed.set(`[${url}](${url})`, url);*/
  if (/^https?:\/\/\S+$/i.test(url)) {
  allowed.set(url, url);
  allowed.set(`[${url}](${url})`, url);
}
}

// Split on level-2 story headings, not level-3 section headings.
const [preamble, ...stories] = output.split(/^##[ \t]+/m);
/*if (preamble.trim() || stories.length !== 20) {
  return fail(`Expected 20 story headings and no preamble; found ${stories.length}.`);
}*/
if (stories.length !== 20) {
  return fail(`Expected 20 story headings; found ${stories.length}.`);
}
if (preamble.trim() && !/^#[ \t]+\S[^\n]*$/.test(preamble.trim())) {
  return fail('Only one optional level-1 title is allowed before Story 1.');
}

const seen = new Set();
for (const [i, story] of stories.entries()) {
  const n = i + 1;
  const [heading, ...lines] = story.split('\n');
 if (!new RegExp(`^${n}\\.?[ \\t]+\\S`).test(heading)) {
  return fail(`Story ${n} must start with "## ${n} Headline" or "## ${n}. Headline".`);
}

  const parts = lines.join('\n').split(/^### Source URL[ \t]*$/m);
  if (parts.length !== 2 || !parts[0].trim()) {
    return fail(`Story ${n} needs a body followed by one Source URL section.`);
  }

  const sourceLines = parts[1].split('\n').map(line => line.trim()).filter(Boolean);

// Ignore one optional Markdown divider after the source link.
if (sourceLines[sourceLines.length - 1] === '---') sourceLines.pop();

if (sourceLines.length !== 1) {
  return fail(`Story ${n}: expected exactly one source link.`);
}

const url = allowed.get(sourceLines[0]);
if (!url) {
  return fail(`Story ${n}: source link does not exactly match an input URL.`);
}
if (seen.has(url)) {
  return fail(`Story ${n}: source URL was already used.`);
}
seen.add(url);
}

return [{ json: { valid: true, attempt, output } }];
